def drive(me, enemy, arena):
    dx = enemy.x - me.x
    dy = enemy.y - me.y
    dist = (dx * dx + dy * dy) ** 0.5
    b = bearing_to(dx, dy)
    if b > 15:
        left = 1.0
        right = -0.7
    elif b < -15:
        left = -0.7
        right = 1.0
    else:
        left = 1.0
        right = 1.0
    r = (me.x * me.x + me.y * me.y) ** 0.5
    if r > 5.2:
        bc = bearing_to(-me.x, -me.y)
        if bc > 0:
            left = 0.5
            right = -1.0
        else:
            left = -1.0
            right = 0.5
    return (left, right)


def weapons(me, enemy, arena):
    cmds = []
    w = me.weapons.get("front")
    if w is not None and w.get("type") == "spinner":
        cmds.append(spin("front", 3300))
    f = me.weapons.get("back")
    if f is not None and f.get("type") == "flipper":
        dx = enemy.x - me.x
        dy = enemy.y - me.y
        dist = (dx * dx + dy * dy) ** 0.5
        b = bearing_to(dx, dy)
        if f.get("ready") and f.get("shots_left", 0) > 0:
            if me.inverted:
                if dist > 2.5:
                    cmds.append(self_right())
            elif me.on_side:
                cmds.append(self_right())
            elif abs(b) > 115 and dist < 1.2:
                cmds.append(flip("back"))
    return cmds

def clamp(v, lo, hi):
    if v < lo:
        return lo
    if v > hi:
        return hi
    return v

def drive(me, enemy, arena):
    if not me.can_drive:
        return (0.0, 0.0)

    base = 0.75
    if me.inverted:
        base = 0.55
    if me.held:
        base = 0.9
    if me.lifted:
        base = 0.35
    if me.battery_health < 0.2:
        base = 0.5

    r2 = me.x * me.x + me.y * me.y
    er2 = enemy.x * enemy.x + enemy.y * enemy.y

    if r2 > 25.0:
        if er2 < 16.0:
            turn = bearing_to(0.0, 0.0)
            if base > 0.65:
                base = 0.65
        else:
            turn = bearing_to(enemy.x, enemy.y)
    else:
        turn = bearing_to(enemy.x, enemy.y)

    turn = clamp(turn, -60.0, 60.0)
    t = turn / 60.0

    left = clamp(base - t, -1.0, 1.0)
    right = clamp(base + t, -1.0, 1.0)
    return (left, right)

