def drive(me, enemy, arena):
    if not me.can_drive:
        return (0.0, 0.0)

    dx = enemy.x - me.x
    dy = enemy.y - me.y
    dist = hypot(dx, dy)
    es = hypot(enemy.vx, enemy.vy)

    if dist > 1.8:
        lead = dist / max(3.5, es + 3.5)
        if lead > 1.2:
            lead = 1.2
        tx = enemy.x + enemy.vx * lead
        ty = enemy.y + enemy.vy * lead
    else:
        tx = enemy.x
        ty = enemy.y

    tr = hypot(tx, ty)
    safe = 4.7
    if tr > safe:
        tx = tx * safe / tr
        ty = ty * safe / tr

    mr = hypot(me.x, me.y)
    if mr > 4.9 and dist > 1.0:
        tx = tx * 0.5
        ty = ty * 0.5
        tr = hypot(tx, ty)
        if tr > safe:
            tx = tx * safe / tr
            ty = ty * safe / tr

    turn = bearing_to(tx, ty)
    base = 1.0

    if me.inverted:
        base = 0.90
    if me.lifted:
        base = 0.50
    if me.battery_wh < 300.0:
        base = 0.75
    elif me.battery_health < 0.25:
        base = 0.85

    at = abs(turn)
    if at > 80.0:
        base = base * 0.60
    elif at > 50.0:
        base = base * 0.80
    elif at > 30.0:
        base = base * 0.92

    t = turn / 60.0
    if t < -1.0:
        t = -1.0
    elif t > 1.0:
        t = 1.0

    left = base - t
    right = base + t

    if left < -1.0:
        left = -1.0
    elif left > 1.0:
        left = 1.0

    if right < -1.0:
        right = -1.0
    elif right > 1.0:
        right = 1.0

    return (left, right)


