def drive(me, enemy, arena):
    if not me.can_drive:
        return (0.0, 0.0)

    dx = enemy.x - me.x
    dy = enemy.y - me.y
    dist = hypot(dx, dy)
    es = hypot(enemy.vx, enemy.vy)

    if dist > 1.6:
        lead = dist / (es + 3.0)
        if lead > 1.0:
            lead = 1.0
    else:
        lead = 0.2

    tx = enemy.x + enemy.vx * lead
    ty = enemy.y + enemy.vy * lead

    if dist < 0.9 and dist > 0.05:
        px = -dy / dist
        py = dx / dist
        h = radians(me.heading)
        side = cos(h) * dy - sin(h) * dx
        if side >= 0.0:
            tx = tx + px * 0.35
            ty = ty + py * 0.35
        else:
            tx = tx - px * 0.35
            ty = ty - py * 0.35

    tr = hypot(tx, ty)
    safe = 4.6
    if tr > safe:
        tx = tx * safe / tr
        ty = ty * safe / tr

    mr = hypot(me.x, me.y)
    if mr > 4.8 and dist > 0.8:
        tx = tx * 0.5
        ty = ty * 0.5
        tr = hypot(tx, ty)
        if tr > safe:
            tx = tx * safe / tr
            ty = ty * safe / tr

    turn = bearing_to(tx, ty)
    base = 1.0

    if me.inverted:
        base = 0.92
    if me.lifted:
        base = 0.50
    if me.battery_wh < 120.0:
        base = 0.70
    if dist < 0.6:
        base = base * 0.75

    at = abs(turn)
    if at > 90.0:
        base = base * 0.55
    elif at > 60.0:
        base = base * 0.75
    elif at > 35.0:
        base = base * 0.90

    t = turn / 55.0
    t = t - me.turn_rate / 300.0
    if t < -1.0:
        t = -1.0
    elif t > 1.0:
        t = 1.0

    left = base - t
    right = base + t

    if left < -1.0:
        left = -1.0
    elif left > 1.0:
        left = 1.0

    if right < -1.0:
        right = -1.0
    elif right > 1.0:
        right = 1.0

    return (left, right)


